```verilog
`timescale 1ns/1ps

module tb;
    reg clk;
    reg reset;
    wire [31:0] q;

    // Instantiate the DUT according to the strict contract
    TopModule dut (
        .clk(clk),
        .reset(reset),
        .q(q)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    integer errors = 0;
    integer i;

    // Reference model for 32-bit Galois LFSR with taps at 32, 22, 2, 1 (0-indexed: 31, 21, 1, 0)
    function [31:0] lfsr_step;
        input [31:0] current_q;
        reg feedback;
        begin
            feedback = current_q[31];
            lfsr_step = {current_q[30:0], 1'b0} ^ (feedback ? 32'h8040_0003 : 32'h0);
        end
    endfunction

    reg [31:0] expected_q;

    initial begin
        // Initialize signals
        clk = 0;
        reset = 1;
        expected_q = 32'h1;

        // Apply reset for a couple of cycles
        @(posedge clk);
        #1;
        if (q !== 32'h1) begin
            errors = errors + 1;
        end

        @(posedge clk);
        #1;
        reset = 0;

        // Run through 20 test vectors/cycles
        for (i = 0; i < 20; i = i + 1) begin
            @(posedge clk);
            expected_q = lfsr_step(expected_q);
            #1; // Wait slightly after clock edge for DUT to update

            // Use case inequality as required by the contract
            if (q !== expected_q) begin
                errors = errors + 1;
            end
        end

        // Report final test result
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end

        $finish;
    end

endmodule
